    document.head.appendChild(style);
  }

  function createUI() {
    if (document.getElementById("reLoggerModernRoot")) {
      return;
    }

    const root = document.createElement("div");

    root.id = "reLoggerModernRoot";

    root.innerHTML = `
      <div
        id="reLoggerModernPanel"
      >
        <div class="relog-header">
