      <div
        id="reLoggerToast" role="status" aria-live="polite"
      ></div>
    `;

    document.body.appendChild(root);
    document
      .getElementById("reLoggerConnect")
      .addEventListener("click", async () => {
        if (await desk.pair()) {
          await GM.setValue("deskSyncedEvents", []);
          syncToDesk();
        }
      });
    document
      .getElementById("reLoggerSync")
